import{z as s,x as o,o as B,c as i,q as e,j as t,D as a,d as l,s as n,S as r}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"Agent 工程收束","description":"","frontmatter":{"title":"Agent 工程收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/agent-map.md","filePath":"llm/agent-map.md","lastUpdated":1791413859000}'),m={name:"llm/agent-map.md"};function C(g,E,h,p,d,D){const A=o("Mermaid");return B(),i("div",null,[E[2]||(E[2]=e('<h1 id="agent-工程收束" tabindex="-1">Agent 工程收束 <a class="header-anchor" href="#agent-工程收束" aria-label="Permalink to &quot;Agent 工程收束&quot;">​</a></h1><div class="epigraph"><p>Agent 工程是把一次补全变成可审计、可恢复、可预算的劳动过程；模型负责决定，系统负责让每个决定都有账可查。</p><footer>—— 据本课程整理；循环与代理谱系见 Yao et al., ICLR 2023 与 Wang 等，2024</footer></div><p><a href="/llm/agent-production-cases">上一课</a>用失败编目给真实系统对账，十三课至此走完——本课程到此收束。收束做两件事：把课程收进几条线，把本课程放回大图，留给后课一个干净的接口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收束要防的仍是把课程读成技巧堆砌：循环、schema、压缩、熔断、围栏、影子流量，单看都是工程技巧，合起来才是一套方法。散着记，换一个模型、换一个任务域就全部重来；收进结构，重算的只有常数。<span class="marginnote">直觉类比：学做菜时，「先焯水再下锅」的次序是结构，换什么灶都成立；具体几分钟、几克盐是常数，换锅换灶就要重调。模型换代相当于换了台灶——火候全部重调，做菜的次序不用重学。</span>所以收束的问题不是复述，是提炼：十三课里哪些是不随模型与任务域改变的结构，哪些只是本次部署的常数。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条线。<strong>架构线</strong>是「架构」单元四课：<a href="/llm/agent-loop-design-space">Agent 循环的设计空间</a>立五根轴、把循环读成转移核；<span class="marginnote">术语翻译：「转移核」是概率论借来的词，指「系统下一步往哪走、按什么规则走」的那套规则。放在代理上就是：给定当前上下文，模型会选什么动作、工具会回什么观察——这两个「会怎样」合起来，就是这个循环的转移核。</span><a href="/llm/agent-tool-protocol-deep">工具协议深钻</a>把动作写成有 schema、有配对、有错误通道的契约；<a href="/llm/agent-context-strategies">上下文管理策略</a>把注意力预算花在未决状态上；<a href="/llm/agent-memory-implementation">记忆系统的实现</a>给窗口外的细节安家。这条线回答「下一步由谁、按什么协议、看到什么地决定」。<strong>质量线</strong>是编排到成本四课：<a href="/llm/agent-multi-orchestration">多 Agent 编排模式</a>按信息流与权限流切分、<a href="/llm/agent-error-recovery">错误恢复与重试</a>给四级失败配四级药、<a href="/llm/agent-eval-success-process">评测：任务成功率与过程</a>用 pass@k 与 \\(\\mathrm{pass}^k\\) 双口径量稳定性、<a href="/llm/agent-cost-latency">成本与延迟优化</a>把杠杆按平方律排序。<strong>生产线</strong>是最后五课：<a href="/llm/agent-guardrails">安全围栏</a>立损失上限、<a href="/llm/agent-observability">可观测性</a>记版本化轨迹账本、<a href="/llm/agent-regression-rollback">回归测试与版本回滚</a>守变更、<a href="/llm/agent-production-cases">生产案例与失败模式</a>编目失败。三条线是同一句话的三种说法：Agent 工程是把一次补全变成可审计、可恢复、可预算的劳动过程。</p>',7)),(B(),t(r,null,{default:a(()=>[n(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOOP%5B%22%E5%BE%AA%E7%8E%AF%EF%BC%9A%E4%BA%94%E6%A0%B9%E8%BD%B4%E4%B8%8E%E8%BD%AC%E7%A7%BB%E6%A0%B8%22%5D%20--%3E%20PROTO%5B%22%E5%8D%8F%E8%AE%AE%EF%BC%9Aschema%20%E4%B8%8E%E9%85%8D%E5%AF%B9%E5%A5%91%E7%BA%A6%22%5D%0A%20%20PROTO%20--%3E%20CTX%5B%22%E4%B8%8A%E4%B8%8B%E6%96%87%EF%BC%9A%E6%B3%A8%E6%84%8F%E5%8A%9B%E9%A2%84%E7%AE%97%22%5D%0A%20%20CTX%20--%3E%20MEM%5B%22%E8%AE%B0%E5%BF%86%EF%BC%9A%E5%88%86%E5%B1%82%E4%B8%8E%E5%8F%8C%E6%97%B6%E9%97%B4%E8%BD%B4%22%5D%0A%20%20MEM%20--%3E%20ORCH%5B%22%E7%BC%96%E6%8E%92%EF%BC%9A%E9%9A%94%E7%A6%BB%E4%B8%8E%E9%80%9A%E4%BF%A1%E7%A8%8E%22%5D%0A%20%20ORCH%20--%3E%20REC%5B%22%E6%81%A2%E5%A4%8D%EF%BC%9A%E5%9B%9B%E7%BA%A7%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20REC%20--%3E%20EVAL%5B%22%E8%AF%84%E6%B5%8B%EF%BC%9A%E7%BB%93%E6%9E%9C%E4%B8%8E%E8%BF%87%E7%A8%8B%E5%8F%8C%E5%8F%A3%E5%BE%84%22%5D%0A%20%20EVAL%20--%3E%20COST%5B%22%E6%88%90%E6%9C%AC%EF%BC%9A%E5%B9%B3%E6%96%B9%E5%BE%8B%E4%B8%8E%E6%9D%A0%E6%9D%86%E5%BA%8F%22%5D%0A%20%20COST%20--%3E%20GATE%5B%22%E5%9B%B4%E6%A0%8F%EF%BC%9A%E6%8D%9F%E5%A4%B1%E4%B8%8A%E9%99%90%22%5D%0A%20%20GATE%20--%3E%20OBS%5B%22%E8%A7%82%E6%B5%8B%EF%BC%9A%E8%BD%A8%E8%BF%B9%E8%B4%A6%E6%9C%AC%22%5D%0A%20%20OBS%20--%3E%20REG%5B%22%E5%9B%9E%E5%BD%92%E4%B8%8E%E5%9B%9E%E6%BB%9A%22%5D%0A%20%20REG%20--%3E%20CASE%5B%22%E5%A4%B1%E8%B4%A5%E7%BC%96%E7%9B%AE%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>放回大图。往回接：<a href="/llm/agent-harness-design">Agent Harness 设计</a>铸的环、<a href="/llm/react">多步 ReAct</a> 立的协议，是本课程的地基；<a href="/llm/lc-map">长上下文收束</a>的账本纪律在这里续写——轨迹是会自己变长的上下文，补账、立契、设门禁的次序原样适用。往前接：训练侧的闭环正在把本课程的账本变成原料——<a href="/llm/tool-integrated-rl">工具整合推理 RL</a> 与 <a href="/llm/agent-lightning">Agent Lightning</a> 把环内轨迹搬进训练循环，<a href="/llm/self-improvement-loop">自改进回路的解剖</a>把线上失败接回数据引擎：部署即采集，观测课的轨迹账本是回路的第一环。模型换代时，常数全部重测：预算阈值、压缩触发点、围栏误杀率、级联判据；结构不变：五根轴、四级失败、双口径、四层围栏、三分结束语义。这就是收束留下的接口：后课遇到「更自主的东西」，先分轴，再立契约，后设门禁，最后记账。</p><p><span class="marginnote">一句自检：任何「代理方案」若说不清五根轴各取什么值、失败分几级各配什么药、轨迹记在哪本账上，它就还只是一个演示——演示在下一个任务域失效，结构不会。</span></p>',3)),(B(),t(r,null,{default:a(()=>[n(A,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20BACK%5B%22%E5%BE%80%E5%9B%9E%E6%8E%A5%EF%BC%9A%E5%9C%B0%E5%9F%BA%22%5D%0A%20%20%20%20H%5B%22Harness%20%E9%93%B8%E7%8E%AF%22%5D%20---%20R%5B%22ReAct%20%E7%AB%8B%E5%8D%8F%E8%AE%AE%22%5D%20---%20LC%5B%22%E9%95%BF%E4%B8%8A%E4%B8%8B%E6%96%87%E7%9A%84%E8%B4%A6%E6%9C%AC%E7%BA%AA%E5%BE%8B%22%5D%0A%20%20end%0A%20%20subgraph%20CORE%5B%22%E6%9C%AC%E8%AF%BE%E7%A8%8B%EF%BC%9A%E4%B8%89%E6%9D%A1%E7%BA%BF%22%5D%0A%20%20%20%20A%5B%22%E6%9E%B6%E6%9E%84%E7%BA%BF%EF%BC%9A%E8%B0%81%E5%86%B3%E5%AE%9A%E4%B8%8B%E4%B8%80%E6%AD%A5%22%5D%20---%20Q%5B%22%E8%B4%A8%E9%87%8F%E7%BA%BF%EF%BC%9A%E5%A4%B1%E8%B4%A5%E4%B8%8E%E6%88%90%E6%9C%AC%E5%AE%9A%E4%BB%B7%22%5D%20---%20O%5B%22%E7%94%9F%E4%BA%A7%E7%BA%BF%EF%BC%9A%E5%9B%B4%E6%A0%8F%C2%B7%E8%A7%82%E6%B5%8B%C2%B7%E5%9B%9E%E5%BD%92%22%5D%0A%20%20end%0A%20%20subgraph%20FWD%5B%22%E5%BE%80%E5%89%8D%E6%8E%A5%EF%BC%9A%E9%97%AD%E7%8E%AF%22%5D%0A%20%20%20%20RL%5B%22%E8%BD%A8%E8%BF%B9%E8%BF%9B%20RL%20%E8%AE%AD%E7%BB%83%22%5D%20---%20SI%5B%22%E5%A4%B1%E8%B4%A5%E6%8E%A5%E5%9B%9E%E6%95%B0%E6%8D%AE%E5%BC%95%E6%93%8E%22%5D%0A%20%20end%0A%20%20BACK%20--%3E%20CORE%0A%20%20CORE%20--%3E%20FWD%0A%20%20LC%20-.%20%22%E8%BD%A8%E8%BF%B9%3D%E4%BC%9A%E8%87%AA%E5%B7%B1%E5%8F%98%E9%95%BF%E7%9A%84%E4%B8%8A%E4%B8%8B%E6%96%87%22%20.-%3E%20A%0A%20%20O%20-.%20%22%E8%BD%A8%E8%BF%B9%E8%B4%A6%E6%9C%AC%3D%E8%AE%AD%E7%BB%83%E5%8E%9F%E6%96%99%22%20.-%3E%20RL%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程是工程侧的收束：训练侧如何造出更会走环的模型（RL 训练系统一线）、评测基准的内部构造、多代理的理论分析，各有其课，这里只接口。案例数字随产品与模型过期；结构跨域复用。深钻层在此收束一门课，不收束一个领域：模型的时间视界还在涨，这本账会一直写下去。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三条线收束：架构线分配「下一步」的决定权，质量线给失败与成本定价，生产线守住发布。</li><li>核心句式：Agent 工程是把一次补全变成可审计、可恢复、可预算的劳动过程。</li><li>往回接 harness 与长上下文两课，往前接 RL 轨迹闭环：账本既是运维证据，也是训练原料。<span class="marginnote">为什么重要：轨迹账本不只是出了事查日志用的——它会被搬进 RL 训练循环当原料。这一步记漏了版本、记错了观察，运维顶多查不清一次事故，训练侧却是把带毒的数据喂进了下一版模型，错误会被固化。</span></li><li>常数随模型与任务域重测，结构（五根轴、四级失败、双口径、四层围栏）跨域复用。</li><li>遇到「更自主的东西」：先分轴，再立契约，后设门禁，最后记账。</li><li>出处：本课程各课口径汇总——Yao et al., ICLR 2023；Schick et al., 2023；Shinn et al., 2023；Wang 等，2024；其余见各课小节。</li></ul>',4))])}const f=s(m,[["render",C]]);export{c as __pageData,f as default};
